-doc """
Return the canonical Decaf448 generator from RFC 9496.

Use this point for interoperable generator multiplication.
The base-scalar multiplication operation uses its built-in precomputed table.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_base() -> Result when
    Result :: decaf448_point().
decaf448_base() ->
    ?nif_stub.

-doc """
Multiply the canonical Decaf448 generator by `Scalar`.

Uses the native library's built-in precomputed generator table.
The scalar must already be canonical; otherwise raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_base_scalarmul(Scalar) -> Result when
    Scalar :: decaf448_scalar(), Result :: decaf448_point().
decaf448_base_scalarmul(_Scalar) ->
    ?nif_stub.

-doc """
Return the Decaf448 identity element, encoded as 56 zero bytes.

Adding this point leaves the other point unchanged. Multiplication by zero
and multiplication of the identity by any scalar both return the identity.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_identity() -> Result when
    Result :: decaf448_point().
decaf448_identity() ->
    ?nif_stub.

-doc """
Return the canonical encoding of `Left + Right`.

Both operands must be valid point encodings; otherwise raises `badarg`.
Adding a point to its negation returns the identity.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_add(Left, Right) -> Result when
    Left :: decaf448_point(), Right :: decaf448_point(), Result :: decaf448_point().
decaf448_point_add(_Left, _Right) ->
    ?nif_stub.

-doc """
Return `Point + Point` in canonical encoding.

This is equivalent to multiplication by the scalar two.
An invalid point encoding raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_double(Point) -> Result when
    Point :: decaf448_point(), Result :: decaf448_point().
decaf448_point_double(_Point) ->
    ?nif_stub.

-doc """
Return `Scalar1 * Point1 + Scalar2 * Point2` in canonical encoding.

Computes the same result as two scalar multiplications followed by addition.
Both points must be valid and both scalars canonical; otherwise raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_double_scalarmul(Point1, Scalar1, Point2, Scalar2) -> Result when
    Point1 :: decaf448_point(),
    Scalar1 :: decaf448_scalar(),
    Point2 :: decaf448_point(),
    Scalar2 :: decaf448_scalar(),
    Result :: decaf448_point().
decaf448_point_double_scalarmul(_Point1, _Scalar1, _Point2, _Scalar2) ->
    ?nif_stub.

-doc """
Return whether two encoded points represent the same group element.

Both operands are decoded and validated. Invalid encodings raise `badarg`;
`false` means that two valid points differ.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_eq(Left, Right) -> Result when
    Left :: decaf448_point(), Right :: decaf448_point(), Result :: boolean().
decaf448_point_eq(_Left, _Right) ->
